// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListChanges Changes after a revision
	// (GET /changes)
	ListChanges(ctx context.Context, request ListChangesRequestObject) (ListChangesResponseObject, error)
	// CreateDiscovery Work out how to read a site
	// (POST /discoveries)
	CreateDiscovery(ctx context.Context, request CreateDiscoveryRequestObject) (CreateDiscoveryResponseObject, error)
	// ListLogs What the catalogue logged lately
	// (GET /logs)
	ListLogs(ctx context.Context, request ListLogsRequestObject) (ListLogsResponseObject, error)
	// CreateProbe Dry-run discovery
	// (POST /probes)
	CreateProbe(ctx context.Context, request CreateProbeRequestObject) (CreateProbeResponseObject, error)
	// CreateSource Create a source
	// (POST /sources)
	CreateSource(ctx context.Context, request CreateSourceRequestObject) (CreateSourceResponseObject, error)
	// DeleteSource Delete a source and its entries
	// (DELETE /sources/{id})
	DeleteSource(ctx context.Context, request DeleteSourceRequestObject) (DeleteSourceResponseObject, error)
	// UpdateSource Update a source
	// (PATCH /sources/{id})
	UpdateSource(ctx context.Context, request UpdateSourceRequestObject) (UpdateSourceResponseObject, error)
	// ListCrawlLog The crawl log of a source
	// (GET /sources/{id}/crawl-log)
	ListCrawlLog(ctx context.Context, request ListCrawlLogRequestObject) (ListCrawlLogResponseObject, error)
	// GetCrawledPage The page the crawl gave up on
	// (GET /sources/{id}/crawl-log/{entry}/page)
	GetCrawledPage(ctx context.Context, request GetCrawledPageRequestObject) (GetCrawledPageResponseObject, error)
	// RequestCrawl Ask for a crawl
	// (POST /sources/{id}/crawls)
	RequestCrawl(ctx context.Context, request RequestCrawlRequestObject) (RequestCrawlResponseObject, error)
	// ClearDemand Say that nobody is reading a source
	// (DELETE /sources/{id}/demand)
	ClearDemand(ctx context.Context, request ClearDemandRequestObject) (ClearDemandResponseObject, error)
	// SetDemand Say how far readers have got
	// (PUT /sources/{id}/demand)
	SetDemand(ctx context.Context, request SetDemandRequestObject) (SetDemandResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

